const sops = [
  ["SOP-001", "Cannot log in to an application after a password reset", "A single user reset their password and now gets invalid credentials in Salesforce, CRM or another single sign-on application.", "1) Ask the user to wait 15 minutes, because the new password takes time to sync to all applications. 2) Ask them to sign in through the company single sign-on portal, not a saved bookmark, and to delete any saved password in the browser. 3) If it still fails, check the account in the identity admin console and unlock it if it shows as locked. 4) If multi-factor prompts fail, reset the MFA registration and have the user enrol again."],
  ["SOP-002", "User account is locked out", "A user is locked out after too many wrong password attempts and cannot sign in to anything.", "1) Verify the user identity with two details from the HR record. 2) Unlock the account in Active Directory. 3) Check the lockout source to see which device keeps sending the old password. 4) Ask the user to update the saved password on their phone mail app and Wi-Fi profile, which are the usual cause of repeat lockouts."],
  ["SOP-003", "Major incident: many users cannot use a business system", "A whole team, office or company cannot access a business critical system such as CRM, ERP, email or the network. Priority P1.", "1) Do not attempt a fix alone. Declare a major incident and page the on-call engineer. 2) Check the vendor status page and the change calendar for a change in the last 24 hours. 3) Open an incident bridge call and name one incident lead. 4) Send a status update to affected users every 30 minutes until service is restored. 5) Record the timeline for the post-incident review."],
  ["SOP-004", "Outlook is not sending or receiving email", "One user reports that Outlook does not send or receive mail.", "1) Check the Microsoft 365 service health page for a mail incident. 2) Ask the user to test Outlook on the web. If web mail works, the problem is the desktop app. 3) Restart Outlook and check it is not in Work Offline mode. 4) Check the mailbox is not over its storage quota. 5) If still failing, create a new Outlook profile."],
  ["SOP-005", "Slow or unstable Wi-Fi in one room", "Users report slow Wi-Fi or frozen video calls in one meeting room or area while other areas are fine.", "1) Check the access point for that room in the wireless controller for high client count or errors. 2) Ask the user to connect to the 5 GHz corporate network, not the guest network. 3) Restart the access point outside meeting hours. 4) If the problem returns, log it for the network team with the room name and the time of day."],
  ["SOP-006", "Suspected phishing or password entered on a fake site", "A user clicked a suspicious link or typed their password into a page they do not trust. Security incident, always needs a human.", "1) Reset the user password immediately and sign out all active sessions. 2) Check that multi-factor authentication is enabled on the account. 3) Ask the user to forward the email as an attachment to the security mailbox, then delete it. 4) Hand over to the security team to check sign-in logs for unknown locations. Do not close the ticket until security confirms."],
  ["SOP-007", "Laptop does not power on", "A laptop shows a black screen or does not start.", "1) Unplug the charger, hold the power button for 30 seconds, then plug in and try again. 2) Try a different charger and power socket. 3) If it still does not start, issue a loaner laptop so the user can work. 4) Raise a hardware repair request with the asset tag."],
  ["SOP-008", "Request for access to a shared folder", "A user asks for access to a shared drive or team folder.", "1) Identify the folder owner from the access register. 2) Ask the owner to approve the request in writing. 3) Add the user to the matching security group, never to the folder directly. 4) Tell the user access starts after they sign out and sign in again."],
  ["SOP-009", "Lost or stolen company phone or laptop", "A user reports a lost or stolen device that holds company data. Security incident, always needs a human.", "1) Lock the device remotely in the device management console. 2) Reset the user password and sign out all sessions. 3) If the device is not found within 24 hours, send a remote wipe. 4) Report the loss to the security team and record the asset tag."],
  ["SOP-010", "Printer keeps jamming", "A shared office printer jams repeatedly.", "1) Ask users to print to the nearest other printer for now. 2) Open the paper trays and remove any torn paper. 3) Check the paper is the correct type and not damp. 4) If jams continue, log a call with the printer supplier and quote the printer serial number."]
];

return sops.map(s => ({
  json: {
    sop_id: s[0],
    title: s[1],
    text: s[0] + ": " + s[1] + "\nWhen to use: " + s[2] + "\nSteps: " + s[3]
  }
}));
